"use client";

import { useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Select } from "@/components/ui/select";

const categories = ["All", "Preliminary", "Written", "Full Syllabus"];

export function MockExamsFilter() {
  const [active, setActive] = useState("All");

  return (
    <div className="mt-2 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
      <div
        className="
          -mx-4 flex flex-nowrap gap-2 overflow-x-auto px-4
          sm:mx-0 sm:flex-wrap sm:overflow-visible sm:px-0
        "
      >
        {categories.map((category) => (
          <button
            key={category}
            type="button"
            onClick={() => {
              setActive(category);
              console.log("category", category);
            }}
          >
            <Badge
              className={
                active === category
                  ? "cursor-pointer rounded-full border-primary bg-primary px-4 py-1.5 text-cream"
                  : "cursor-pointer rounded-full border-border px-4 py-1.5 text-muted transition-colors hover:border-primary hover:text-primary"
              }
            >
              {category}
            </Badge>
          </button>
        ))}
      </div>
      <Select className="h-10 w-full sm:w-48" aria-label="Sort mock exams">
        <option>Newest</option>
        <option>Oldest</option>
        <option>Popularity</option>
      </Select>
      <p className="sr-only">
        NOTE: static filter UI — wire to URL query params in a later pass.
      </p>
    </div>
  );
}
